-- Replace exactly 12 published flag-history questions (Canada, France, Germany, South Africa)
-- with 12 evidence-based questions on Russian flag, coat of arms and anthem.
-- Preserve question UUIDs, published/round tags, topic, mode and existing saved-room snapshots.
-- Expected correct-index distribution: A/B/C/D = 3/3/3/3.
DO $replace_symbols$
DECLARE x record; n integer; updated integer:=0;
BEGIN
 FOR x IN
 SELECT * FROM (VALUES
  ('6827a986-fa08-469c-917a-7d2ff75bfed9'::uuid,'Когда состоялось торжественное первое поднятие современного флага Канады?','В каком порядке расположены цвета государственного флага России сверху вниз?','["Красный, белый, синий","Синий, белый, красный","Белый, синий, красный","Белый, красный, синий"]'::jsonb,2,'Верхняя полоса белая, средняя синяя, нижняя красная. Это закреплено в статье 1 ФКЗ № 1-ФКЗ.','https://www.consultant.ru/document/cons_doc_LAW_29679/c41c70f20e06e363bebf1c663ad3ed3259b27c57/'),
  ('0c3700d5-aad0-4d6d-ad67-68c5cc17f205'::uuid,'Сколько концов у стилизованного кленового листа на современном флаге Канады?','Каково отношение ширины государственного флага России к его длине?','["2:3","1:2","3:2","1:1"]'::jsonb,0,'По статье 1 ФКЗ «О Государственном флаге Российской Федерации» отношение ширины к длине — 2:3.','https://www.consultant.ru/document/cons_doc_LAW_29679/c41c70f20e06e363bebf1c663ad3ed3259b27c57/'),
  ('8cd6ce01-c504-4b84-8226-6ce6ae853af6'::uuid,'Каково отношение длины современного флага Канады к его высоте?','Какого числа ежегодно отмечается День Государственного флага Российской Федерации?','["12 июня","4 ноября","1 сентября","22 августа"]'::jsonb,3,'День Государственного флага России отмечается 22 августа; праздник установлен указом Президента РФ в 1994 году.','https://www.prlib.ru/node/619167'),
  ('3e8875e3-f3cc-4ca9-9278-cac972d33ecb'::uuid,'Зачем первоначальный 13-конечный лист канадского флага заменили 11-конечным?','Какое решение о бело-сине-красном полотнище было принято 22 августа 1991 года?','["Утверждён современный текст гимна","Его признали официальным флагом РСФСР","Утверждён современный герб России","Принят ФКЗ о государственном флаге"]'::jsonb,1,'22 августа 1991 года Верховный Совет РСФСР постановил использовать бело-сине-красное полотнище как официальный флаг РСФСР.','https://www.prlib.ru/node/619167'),
  ('36d88524-bfe3-4f87-ae8f-4bb565f2138a'::uuid,'В каком году во Франции закрепили порядок вертикальных полос: синий у древка, белый, красный?','Какая птица изображена в центре государственного герба Российской Федерации?','["Золотой двуглавый орёл","Серебряный сокол","Белый лебедь","Чёрный одноглавый орёл"]'::jsonb,0,'На гербе России изображён золотой двуглавый орёл с поднятыми распущенными крыльями.','https://www.consultant.ru/document/cons_doc_LAW_29674/c41c70f20e06e363bebf1c663ad3ed3259b27c57/'),
  ('1d0c3ef1-b7ed-4781-be92-1cc3632fd375'::uuid,'Какой город дал французскому триколору синий и красный цвета согласно описанию Елисейского дворца?','Какие символы держит двуглавый орёл на государственном гербе России?','["Меч и щит","Факел и венок","Скипетр и держава","Ключ и свиток"]'::jsonb,2,'В правой лапе орла — скипетр, в левой — держава, согласно статье 1 ФКЗ о гербе.','https://www.consultant.ru/document/cons_doc_LAW_29674/c41c70f20e06e363bebf1c663ad3ed3259b27c57/'),
  ('825cf99b-423f-4ecd-ad08-fbf689483ecf'::uuid,'Какой цвет, по описанию Елисейского дворца, представлял монархию в истории французского триколора?','Сколько корон изображено над головами орла на государственном гербе России?','["Одна","Две","Четыре","Три"]'::jsonb,3,'Герб изображает две малые короны и одну большую над ними, всего три короны.','https://www.consultant.ru/document/cons_doc_LAW_29674/c41c70f20e06e363bebf1c663ad3ed3259b27c57/'),
  ('0f5d0f54-9f9a-410e-849b-924be987e62e'::uuid,'В каком году Парламентский совет выбрал чёрный, красный и золотой для флага ФРГ?','Какой сюжет изображён на щите на груди двуглавого орла российского герба?','["Медведь с щитом","Серебряный всадник поражает копьём дракона","Лев держит державу","Сокол на ветви"]'::jsonb,1,'На груди орла в красном щите изображён серебряный всадник на коне, поражающий копьём чёрного дракона.','https://www.consultant.ru/document/cons_doc_LAW_29674/c41c70f20e06e363bebf1c663ad3ed3259b27c57/'),
  ('8c13bd99-3d5c-4879-ad7e-4d1054a0cfb1'::uuid,'Какую дату Бундестаг связывает с распространением чёрно-красно-золотого флага на объединённую Германию?','Кто написал музыку современного Государственного гимна Российской Федерации?','["Михаил Глинка","Александр Александров","Сергей Прокофьев","Дмитрий Шостакович"]'::jsonb,1,'Автор музыки гимна России — композитор Александр Васильевич Александров.','https://www.prlib.ru/item/407020'),
  ('dda8a009-9e6e-474c-8a02-b54c6a611a33'::uuid,'Когда современный флаг ЮАР впервые начали использовать?','Кто написал слова действующего Государственного гимна Российской Федерации?','["Василий Лебедев-Кумач","Роберт Рождественский","Сергей Михалков","Александр Твардовский"]'::jsonb,2,'Автор слов действующего гимна России — Сергей Владимирович Михалков.','https://www.prlib.ru/item/407020'),
  ('dae58795-e722-40da-bfb5-c670485953b1'::uuid,'Кто создал современный национальный флаг ЮАР?','Как по закону следует слушать Государственный гимн России при официальном исполнении?','["Стоя","Сидя","Только подняв правую руку","По усмотрению организатора"]'::jsonb,0,'По статье 7 ФКЗ о гимне присутствующие выслушивают его стоя; для мужчин также установлено правило о головных уборах.','https://www.consultant.ru/document/cons_doc_LAW_29673/569c329fe84b5f250b48f6f6563d706c58d77478/'),
  ('86708790-8473-4271-96ae-ad83f1d5abc8'::uuid,'Как ведомство культуры ЮАР объясняет схождение линий рисунка флага в одну полосу?','Когда исполняется Государственный гимн России при вступлении Президента РФ в должность?','["Перед выборами","До принесения присяги","После первого заседания правительства","После принесения присяги"]'::jsonb,3,'Статья 3 ФКЗ о гимне предусматривает исполнение гимна при вступлении Президента РФ в должность после принесения присяги.','https://www.consultant.ru/document/cons_doc_LAW_29673/2d7c9d0b162c44d27d0679d094900ef36cfc72e0/')
 ) AS seed(id,old_prompt,new_prompt,answers,answer_index,explanation,source_url)
 LOOP
  IF jsonb_array_length(x.answers)<>4 OR x.answer_index NOT BETWEEN 0 AND 3 THEN
   RAISE EXCEPTION 'Invalid answer format for %',x.id;
  END IF;
  UPDATE public.qwiz_bank q
  SET prompt=x.new_prompt,
      options=x.answers,
      solution=(coalesce(q.solution,'{}'::jsonb)-'source_urls') ||
        jsonb_build_object('correct',x.answer_index,'flag_mode','history',
                           'source_urls',jsonb_build_array(x.source_url)),
      explanation=x.explanation
  WHERE q.id=x.id
    AND q.prompt=x.old_prompt
    AND q.kind='flag'
    AND q.solution->>'flag_mode'='history'
    AND q.tags @> ARRAY['fw:published','fw:stages7-12']::text[]
    AND EXISTS (SELECT 1 FROM public.qwiz_topics t WHERE t.id=q.topic_id AND t.name='Флаги мира');
  GET DIAGNOSTICS n=ROW_COUNT;
  IF n<>1 THEN RAISE EXCEPTION 'Expected exactly one matched published history question for ID %; found %',x.id,n; END IF;
  updated:=updated+n;
 END LOOP;
 IF updated<>12 THEN RAISE EXCEPTION 'Updated only % of 12 expected records',updated; END IF;
END
$replace_symbols$;
